class Solution {
  public int countStableSubsequences(int[] nums) {
    final long MOD = 1_000_000_007L;
    long[][] dp = new long[2][3];
    for (int x : nums) {
      int p = x & 1;
      long one = (1 + dp[1 - p][1] + dp[1 - p][2]) % MOD;
      long two = dp[p][1];
      dp[p][1] = (dp[p][1] + one) % MOD;
      dp[p][2] = (dp[p][2] + two) % MOD;
    }
    return (int) ((dp[0][1] + dp[0][2] + dp[1][1] + dp[1][2]) % MOD);
  }
}
